import os
from copy import copy
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

OUTPUT_DIR = '/root/output'
INPUT_PATH = '/root/data/workbook.xlsx'
OUTPUT_PATH = '/root/output/result.xlsx'

os.makedirs(OUTPUT_DIR, exist_ok=True)

wb = load_workbook(INPUT_PATH, data_only=False)
ws_task = wb['Task']
ws_data = wb['Data']


def cell_text(v):
    if v is None:
        return ''
    return str(v)


def print_range(ws, min_row, max_row, min_col, max_col, title):
    print(f"\n--- {title}: {ws.title}!{get_column_letter(min_col)}{min_row}:{get_column_letter(max_col)}{max_row} ---")
    headers = ['row'] + [get_column_letter(c) for c in range(min_col, max_col + 1)]
    print('\t'.join(headers))
    for r in range(min_row, max_row + 1):
        vals = [str(r)]
        for c in range(min_col, max_col + 1):
            vals.append(cell_text(ws.cell(r, c).value))
        print('\t'.join(vals))

# Mandatory inspection before writing anything.
print_range(ws_task, 1, 50, 1, 13, 'Inspection')
data_print_max_col = max(26, ws_data.max_column)
print_range(ws_data, 1, 40, 1, data_print_max_col, 'Inspection')

# Helpers for layout identification.
def norm(v):
    if v is None:
        return None
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    if isinstance(v, int):
        return str(v)
    s = str(v).strip()
    if s.endswith('.0'):
        try:
            return str(int(float(s)))
        except Exception:
            return s
    return s

# Per task, target years come from Task row 10, H:L.
year_cols_task = list(range(8, 13))
task_years = [ws_task.cell(10, c).value for c in year_cols_task]
task_year_norms = {norm(v) for v in task_years if norm(v) is not None}

# Find the Data year header row by matching Task years in Data rows 1:40.
best_header = None
best_header_matches = -1
for r in range(1, 41):
    row_norms = {norm(ws_data.cell(r, c).value) for c in range(1, ws_data.max_column + 1)}
    row_norms.discard(None)
    matches = len(task_year_norms & row_norms)
    if matches > best_header_matches:
        best_header_matches = matches
        best_header = r

# The instruction says Data rows 21:38 are the lookup records. Use those rows,
# but infer the series-code/key column from exact matches against Task D codes.
data_first_row = 21
data_last_row = 38
task_code_rows = list(range(12, 18)) + list(range(19, 25)) + list(range(26, 32))
task_codes = {norm(ws_task.cell(r, 4).value) for r in task_code_rows if norm(ws_task.cell(r, 4).value) is not None}

best_key_col = None
best_key_matches = -1
for c in range(1, ws_data.max_column + 1):
    col_norms = {norm(ws_data.cell(r, c).value) for r in range(data_first_row, data_last_row + 1)}
    col_norms.discard(None)
    matches = len(task_codes & col_norms)
    if matches > best_key_matches:
        best_key_matches = matches
        best_key_col = c

if best_header is None or best_header_matches <= 0:
    raise RuntimeError(f"Could not identify Data year header row for Task years {task_years}")
if best_key_col is None or best_key_matches <= 0:
    raise RuntimeError(f"Could not identify Data series-code column for Task codes {sorted(task_codes)}")

# Use the contiguous header/data columns that contain all Task years. Normally B:Z.
year_header_cols = []
for c in range(1, ws_data.max_column + 1):
    if norm(ws_data.cell(best_header, c).value) in task_year_norms:
        year_header_cols.append(c)
if not year_header_cols:
    raise RuntimeError('No Data year columns found')
body_first_col = min(year_header_cols)
body_last_col = max(year_header_cols)
# Expand through the complete year-header band around the matched years, excluding the key column.
# This keeps MATCH and INDEX aligned while avoiding non-year descriptor columns.
# If adjacent nonblank year-like cells exist, include them.
def is_yearish(v):
    nv = norm(v)
    if nv is None:
        return False
    try:
        y = int(nv)
        return 1900 <= y <= 2100
    except Exception:
        return False
while body_first_col > 1 and body_first_col - 1 != best_key_col and is_yearish(ws_data.cell(best_header, body_first_col - 1).value):
    body_first_col -= 1
while body_last_col < ws_data.max_column and body_last_col + 1 != best_key_col and is_yearish(ws_data.cell(best_header, body_last_col + 1).value):
    body_last_col += 1

print('\n--- Identified layout ---')
print(f"Data series-code column: {get_column_letter(best_key_col)}")
print(f"Data year header row: {best_header}")
print(f"Data row-match range: Data!${get_column_letter(best_key_col)}${data_first_row}:${get_column_letter(best_key_col)}${data_last_row}")
print(f"Data column-match/header range: Data!${get_column_letter(body_first_col)}${best_header}:${get_column_letter(body_last_col)}${best_header}")
print(f"Data INDEX body range: Data!${get_column_letter(body_first_col)}${data_first_row}:${get_column_letter(body_last_col)}${data_last_row}")
print(f"Task years H10:L10: {task_years}")

# Verify block/region/stat labels from the sheet.
print('\n--- Task block labels / codes ---')
for label, rows in [('Block 1', range(12, 18)), ('Block 2', range(19, 25)), ('Block 3', range(26, 32)), ('Gap rows', range(35, 41)), ('Stats rows', range(42, 48)), ('Weighted mean row', range(50, 51))]:
    print(label)
    for r in rows:
        print(f"  row {r}: D={ws_task.cell(r,4).value!r}, E={ws_task.cell(r,5).value!r}, F={ws_task.cell(r,6).value!r}, G={ws_task.cell(r,7).value!r}")

# Step 1: two-dimensional INDEX/MATCH lookup formulas.
index_range = f"Data!${get_column_letter(body_first_col)}${data_first_row}:${get_column_letter(body_last_col)}${data_last_row}"
key_range = f"Data!${get_column_letter(best_key_col)}${data_first_row}:${get_column_letter(best_key_col)}${data_last_row}"
header_range = f"Data!${get_column_letter(body_first_col)}${best_header}:${get_column_letter(body_last_col)}${best_header}"

lookup_blocks = [(12, 17), (19, 24), (26, 31)]
for start_row, end_row in lookup_blocks:
    for r in range(start_row, end_row + 1):
        for c in year_cols_task:
            col_letter = get_column_letter(c)
            ws_task.cell(r, c).value = f"=INDEX({index_range}, MATCH($D{r}, {key_range}, 0), MATCH({col_letter}$10, {header_range}, 0))"

# Step 2: net reliability gap formulas.
for r in range(35, 41):
    offset = r - 35
    src1 = 12 + offset
    src2 = 19 + offset
    src3 = 26 + offset
    for c in year_cols_task:
        col_letter = get_column_letter(c)
        ws_task.cell(r, c).value = f"=({col_letter}{src1}-{col_letter}{src2})/{col_letter}{src3}*100"

# Step 3: summary statistics. Confirm labels and map conservatively.
stat_formulas_by_keyword = {
    'min': 'MIN',
    'max': 'MAX',
    'median': 'MEDIAN',
    'mean': 'AVERAGE',
    'average': 'AVERAGE',
    '25': 'PERCENTILE25',
    '75': 'PERCENTILE75',
}
# Defaults from task if labels are absent/ambiguous.
default_stat_rows = {
    42: 'MIN',
    43: 'MAX',
    44: 'MEDIAN',
    45: 'AVERAGE',
    46: 'PERCENTILE25',
    47: 'PERCENTILE75',
}

def stat_type_for_row(r):
    label = ' '.join(cell_text(ws_task.cell(r, c).value).lower() for c in range(4, 8))
    if '75' in label or 'third quartile' in label or 'q3' in label:
        return 'PERCENTILE75'
    if '25' in label or 'first quartile' in label or 'q1' in label:
        return 'PERCENTILE25'
    if 'median' in label:
        return 'MEDIAN'
    if 'mean' in label or 'average' in label:
        return 'AVERAGE'
    if 'max' in label:
        return 'MAX'
    if 'min' in label:
        return 'MIN'
    return default_stat_rows[r]

for r in range(42, 48):
    stat_type = stat_type_for_row(r)
    print(f"Statistic row {r} mapped to {stat_type}")
    for c in year_cols_task:
        col_letter = get_column_letter(c)
        data_range = f"{col_letter}35:{col_letter}40"
        if stat_type == 'MIN':
            formula = f"=MIN({data_range})"
        elif stat_type == 'MAX':
            formula = f"=MAX({data_range})"
        elif stat_type == 'MEDIAN':
            formula = f"=MEDIAN({data_range})"
        elif stat_type == 'AVERAGE':
            formula = f"=AVERAGE({data_range})"
        elif stat_type == 'PERCENTILE25':
            formula = f"=PERCENTILE({data_range},0.25)"
        elif stat_type == 'PERCENTILE75':
            formula = f"=PERCENTILE({data_range},0.75)"
        else:
            raise RuntimeError(f"Unknown stat type {stat_type}")
        ws_task.cell(r, c).value = formula

# Step 4: weighted mean formulas.
for c in year_cols_task:
    col_letter = get_column_letter(c)
    ws_task.cell(50, c).value = f"=SUMPRODUCT({col_letter}35:{col_letter}40, {col_letter}26:{col_letter}31) / SUM({col_letter}26:{col_letter}31)"

wb.save(OUTPUT_PATH)
print(f"\nSaved workbook to {OUTPUT_PATH}")

# Final verification: reopen and print target ranges; assert all target cells contain formula strings.
wb2 = load_workbook(OUTPUT_PATH, data_only=False)
ws2 = wb2['Task']

def print_formula_range(min_row, max_row, min_col, max_col, label):
    print(f"\n--- Verification {label}: Task!{get_column_letter(min_col)}{min_row}:{get_column_letter(max_col)}{max_row} ---")
    all_formula = True
    for r in range(min_row, max_row + 1):
        vals = []
        for c in range(min_col, max_col + 1):
            v = ws2.cell(r, c).value
            vals.append(v if v is not None else 'None')
            if not (isinstance(v, str) and v.startswith('=')):
                all_formula = False
        print(f"row {r}: " + ' | '.join(vals))
    print(f"All formulas in {label}: {all_formula}")
    if not all_formula:
        raise RuntimeError(f"Non-formula/None cell found in {label}")

print_formula_range(12, 17, 8, 12, 'H12:L17')
print_formula_range(19, 24, 8, 12, 'H19:L24')
print_formula_range(26, 31, 8, 12, 'H26:L31')
print_formula_range(35, 40, 8, 12, 'H35:L40')
print_formula_range(42, 47, 8, 12, 'H42:L47')
print_formula_range(50, 50, 8, 12, 'H50:L50')

print('\nVerification complete: every target cell contains an Excel formula string.')
